// func HashF16(input *[16384]byte, length uint64, counter uint64, flags uint32, key *[8]uint32, outLo *[32]uint32, outHi *[32]uint32, chain *[8]uint32)
// Requires: AVX, AVX2, AVX512F
TEXT ·HashF16(SB), $2832-64
	MOVQ input+0(FP), AX
	MOVQ length+8(FP), CX
	MOVQ counter+16(FP), DX
	MOVL flags+24(FP), BX
	MOVQ key+32(FP), SI
	MOVQ outLo+40(FP), DI
	MOVQ outHi+48(FP), R8
	MOVQ chain+56(FP), R9

	// Allocate local space and align it
	LEAQ 63(SP), R12
	ANDQ $-64, R12

	// Skip if the length is zero
	XORQ  R10, R10
	XORQ  R11, R11
	TESTQ CX, CX
	JZ    skip_compute

	// Compute complete chunks and blocks
	SUBQ $0x01, CX
	MOVQ CX, R10
	SHRQ $0x0a, R10
	MOVQ CX, R11
	ANDQ $0x000003c0, R11

skip_compute:
	// Load some params into the stack (avo improvment?)
	MOVL BX, 2752(R12)
	MOVQ DX, 2760(R12)

	// Load IV into vectors
	VPBROADCASTD (SI), Z16
	VPBROADCASTD 4(SI), Z17
	VPBROADCASTD 8(SI), Z18
	VPBROADCASTD 12(SI), Z19
	VPBROADCASTD 16(SI), Z20
	VPBROADCASTD 20(SI), Z21
	VPBROADCASTD 24(SI), Z22
	VPBROADCASTD 28(SI), Z23

	// Build and store counter data on the stack
	VPBROADCASTQ 2760(R12), Y0
	VPADDQ       counter<>+0(SB), Y0, Y0
	VPBROADCASTQ 2760(R12), Y1
	VPADDQ       counter<>+32(SB), Y1, Y1
	VPUNPCKLDQ   Y1, Y0, Y2
	VPUNPCKHDQ   Y1, Y0, Y0
	VPUNPCKLDQ   Y0, Y2, Y1
	VPUNPCKHDQ   Y0, Y2, Y0
	VPERMQ       $0xd8, Y1, Y1
	VPERMQ       $0xd8, Y0, Y0
	VMOVDQU      Y1, 2560(R12)
	VMOVDQU      Y0, 2624(R12)
	VPBROADCASTQ 2760(R12), Y0
	VPADDQ       counter<>+64(SB), Y0, Y0
	VPBROADCASTQ 2760(R12), Y1
	VPADDQ       counter<>+96(SB), Y1, Y1
	VPUNPCKLDQ   Y1, Y0, Y2
	VPUNPCKHDQ   Y1, Y0, Y0
	VPUNPCKLDQ   Y0, Y2, Y1
	VPUNPCKHDQ   Y0, Y2, Y0
	VPERMQ       $0xd8, Y1, Y1
	VPERMQ       $0xd8, Y0, Y0
	VMOVDQU      Y1, 2592(R12)
	VMOVDQU      Y0, 2656(R12)

	// Set up block flags and variables for iteration
	XORQ CX, CX
	ORL  $0x01, 2752(R12)

loop:
